flowchart TD
  READ["obj.method()"] --> OWN{Own property?}
  OWN -->|yes| USE[Use it]
  OWN -->|no| NEXT[[Prototype]]]
  NEXT --> OWN2{Own on parent?}
  OWN2 -->|yes| USE
  OWN2 -->|no| NULL{Prototype null?}
  NULL -->|no| NEXT
  NULL -->|yes| UNDEF[undefined / create own on write]

snippet.code:
function AuthHandler(provider) {
  this.provider = provider;
}

AuthHandler.prototype.parse = function (raw) {
  return { provider: this.provider, raw };
};

const lti = new AuthHandler("lti");

console.log(lti.parse("token")); // { provider: 'lti', raw: 'token' }
console.log(Object.hasOwn(lti, "parse")); // false — inherited
console.log(Object.getPrototypeOf(lti) === AuthHandler.prototype); // true

const base = {
  kind: "handler",
  describe() {
    return this.kind;
  },
};

const lti = Object.create(base);
lti.kind = "lti";

console.log(lti.describe()); // lti — this is lti, method from base
console.log(Object.getPrototypeOf(lti) === base); // true

// Prototype chain: lti -> base -> Object.prototype -> null

const obj = { a: 1 };

// Prefer these:
const proto = Object.getPrototypeOf(obj); // Object.prototype
Object.setPrototypeOf(obj, { b: 2 });     // mutates chain — avoid on hot paths

// Legacy — works but discouraged in new code:
console.log(obj.__proto__ === Object.prototype); // true

console.log(obj.b); // 2 — found on new prototype
console.log(obj.a); // 1 — own property unchanged

function Service() {}
const s = new Service();

console.log(s instanceof Service); // true
console.log(s instanceof Object);  // true — chain reaches Object.prototype

// Manual check equivalent:
console.log(Service.prototype.isPrototypeOf(s)); // true

function User(name) { this.name = name; }
User.prototype.role = "guest";

const admin = new User("Ada");
admin.role = "admin"; // own property shadows prototype

User.prototype.role = "blocked"; // mutates shared prototype!

const bob = new User("Bob");
console.log(bob.role);    // blocked — reads prototype
console.log(admin.role);  // admin — own property wins
